class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return "..."

class Dog(Animal):          # inherits Animal
    def speak(self):        # overrides speak
        return f"{self.name} says Woof!"

d = Dog("Rex")
print(d.speak())   # Rex says Woof!

struct Animal {
    name: String,
}

trait Speak {
    fn speak(&self) -> String;
}

struct Dog {
    animal: Animal,
}

impl Speak for Dog {
    fn speak(&self) -> String {
        format!("{} says Woof!", self.animal.name)
    }
}

let d = Dog { animal: Animal { name: String::from("Rex") } };
println!("{}", d.speak());

class Animal {
    var name: Str
    fn speak() -> Str { return "..." }
}

class Dog : Animal {
    fn speak() -> Str {
        return name + " says Woof!"
    }
}

let d = Dog { name: "Rex" }
print(d.speak())   // Rex says Woof!

/* C: explicit types, manual memory */
#include <stdio.h>

void greet(const char* name) {
    printf("Hello, %s!\n", name);
}

int main(void) {
    greet("World");
    return 0;
}

// Rust: safe, explicit, zero-cost abstractions
fn greet(name: &str) -> String {
    format!("Hello, {}!", name)
}

fn main() {
    println!("{}", greet("World"));
}

// UniLogic: multi-target, statically typed
fn greet(name: Str) -> Str {
    return "Hello, " + name + "!"
}

print(greet("World"))   // Hello, World!
